/** The UI languages, in menu order: [code, native name]. */
export const LANGS = [
  ['en', 'English'], ['zh', '中文'], ['es', 'Español'], ['ko', '한국어'],
  ['ja', '日本語'], ['ru', 'Русский'], ['vi', 'Tiếng Việt'], ['th', 'ไทย'],
];
/** A stored code from LANGS, anything else -> 'en'. */
export const pickLang = (code) => (LANGS.some(([c]) => c === code) ? code : 'en');

/** t(key, vars) for one language; missing keys fall back to English, then the key. */
export function makeT(lang) {
  const d = T[lang] ?? T.en;
  return (key, vars = {}) => {
    const s = d[key] ?? T.en[key] ?? key;
    return s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m));
  };
}
